import re
lines = open('/workspace/results.md', encoding='utf-8').read().splitlines()
# find header line that includes the technique names
hdr_idx = None
for i,l in enumerate(lines):
    if 'PRM-Enumeration' in l or 'Euler' in l or 'ROAM' in l:
        hdr_idx = i
        hdr = l
        break
if hdr_idx is None:
    raise SystemExit('Header line not found')
cells = [c.strip() for c in hdr.split('|')[1:-1]]
name2idx = {name:i for i,name in enumerate(cells)}
# target columns (use the header exact names present)
targets = []
for t in ('PRM-Enumeration','Euler','ROAM'):
    if t in name2idx:
        targets.append((t,name2idx[t]))
    else:
        for k in name2idx:
            if k.upper()==t.upper():
                targets.append((t,name2idx[k]))
                break
# collect data rows (rows starting with |<number>|)
data_rows = []
for l in lines[hdr_idx+2:]:
    if re.match(r'\|\s*\d+\s*\|', l):
        row = [c.strip() for c in l.split('|')[1:-1]]
        data_rows.append(row)
def parse_num(s):
    if s is None: return None
    m = re.search(r'([0-9]*\.?[0-9]+)', s)
    if not m: return None
    try:
        return float(m.group(1))
    except:
        return None
results = {}
for name,idx in targets:
    vals = []
    for r in data_rows:
        if idx < len(r):
            v = parse_num(r[idx])
            if v is not None:
                vals.append(v)
    if len(vals)==0:
        avg = perfect = zero = 0.0
    else:
        avg = sum(vals)/len(vals)
        perfect = sum(1 for v in vals if abs(v-1.0)<1e-9)/len(vals)
        zero = sum(1 for v in vals if abs(v-0.0)<1e-9)/len(vals)
    results[name] = (avg*100, perfect*100, zero*100)
# Output in a simple tab-separated form (Technique, MatchAccuracy%, Perfect%, Zero%)
print("Technique\tMatch Accuracy\tPerfect Cases\tZero Cases")
for t in ('PRM-Enumeration','Euler','ROAM'):
    if t in results:
        a,p,z = results[t]
        print(f"{t}\t{a:.1f}%\t{p:.1f}%\t{z:.1f}%")
    else:
        print(f"{t}\tN/A\tN/A\tN/A")
PY
# Section 4: Format the result into the expected table with artisan format and surround with the required <artisan_submit> block
echo '<artisan_submit>'
artisan format --expected /workspace/expected.md --repro /workspace/repro.txt
echo '</artisan_submit>'

#!/usr/bin/bash
# Section 1: Write the expected table to /workspace/expected.md
cat > /workspace/expected.md << 'EOTABLE'
**Table 3: Reproduction Rate of Each Approach (Shown as a Percent)**

|          | All Reports | Reports w/o Missing Steps | Reports w/ Missing Steps |
| -------- | :---------: | :-----------------------: | :----------------------: |
| ReCDroid |      ??     |             ??            |            ??            |
| Yakusu   |      ?      |             ??            |             ?            |
| Roam     |      ??     |             ??            |            ??            |

EOTABLE

# Section 2: Download and extract the artifact
artisan get https://zenodo.org/records/11068809

# Section 3: Run the commands to reproduce the results
# Convert the provided results.pdf to markdown
uvx --from pymupdf4llm python -c 'import sys, pymupdf4llm as p; sys.stdout.write(p.to_markdown(sys.argv[1]))' ROAM-Artifact/ROAM-Artifact/Evaluation/results.pdf > /workspace/results.md

python3 - <<'PY'
import re, sys

md_path = '/workspace/results.md'
out_path = '/workspace/repro.txt'

try:
    with open(md_path, 'r', encoding='utf-8') as f:
        lines = [l.strip() for l in f if l.strip()]
except FileNotFoundError:
    sys.exit('results.md not found')

if not lines:
    sys.exit('results.md is empty')

# 1. Dynamically identify table headers and data start
header1 = []
header2 = []
data_lines = []
sep_idx = -1

# Find the separator line (e.g., |---|---|)
for i, line in enumerate(lines[:10]):  # Scan first 10 lines
    if set(line) <= set('|-: '):
        sep_idx = i
        break

if sep_idx != -1:
    # Line before separator is definitely a header
    header1 = [c.strip() for c in lines[sep_idx-1].split('|')[1:-1]]

    # Check if line AFTER separator is a secondary header (contains text like 'Reproduction' or 'Result')
    # or if it's data.
    if sep_idx + 1 < len(lines):
        candidate = lines[sep_idx+1]
        # Heuristic: if it contains 'reproduction' or 'success' or 'missing', treat as header
        if any(x in candidate.lower() for x in ['reproduction', 'result', 'missing', 'success']):
            header2 = [c.strip() for c in candidate.split('|')[1:-1]]
            data_lines = lines[sep_idx+2:]
        else:
            data_lines = lines[sep_idx+1:]
else:
    # No separator found? Try to assume line 0 is header
    if lines:
        header1 = [c.strip() for c in lines[0].split('|')[1:-1]]
        data_lines = lines[1:]

# Normalize header2 length
if len(header2) < len(header1):
    header2 += [''] * (len(header1) - len(header2))

# 2. Find Missing Steps Column Index
missing_idx = None
# Check header 2 first (more specific)
for i, h in enumerate(header2):
    if 'missing' in h.lower():
        missing_idx = i
        break
# Check header 1
if missing_idx is None:
    for i, h in enumerate(header1):
        if 'missing' in h.lower():
            missing_idx = i
            break
# Fallback: Check for "Steps" if "Missing" not found
if missing_idx is None:
    for headers in [header2, header1]:
        for i, h in enumerate(headers):
            if 'steps' in h.lower():
                missing_idx = i
                break
        if missing_idx is not None: break

if missing_idx is None:
    # Dump headers for debug purposes
    sys.stderr.write(f"Header 1: {header1}\nHeader 2: {header2}\n")
    sys.exit('Missing steps column not found')

# 3. Find Tool Columns
# Helper to check if a column header implies reproduction results
def is_result_col(h):
    h = h.lower()
    return 'reproduction' in h or 'result' in h or 'success' in h

tool_indices = {}
for tool in ['roam', 'recdroid', 'yakusu']:
    found = None
    # Strategy: Find tool name in H1, then look for result col in H2 at similar index
    for i, h in enumerate(header1):
        if tool in h.lower():
            # Tool found in main header. Look for "Reproduction/Result" column nearby
            # Check the exact index first
            if i < len(header2) and is_result_col(header2[i]):
                found = i
                break
            # Check next few columns (header spanning)
            for offset in range(1, 4):
                if i + offset < len(header2) and is_result_col(header2[i+offset]):
                    found = i + offset
                    break
            # If no subheader found, assume the main header column is the one
            if found is None:
                found = i
            break

    # If not found in H1, check if H1+H2 combined string matches (weird formatting)
    if found is None:
        for i, (h1, h2) in enumerate(zip(header1, header2)):
            if tool in (h1 + ' ' + h2).lower() and is_result_col(h2):
                found = i
                break

    tool_indices[tool.lower()] = [found] if found is not None else []

# 4. Process Rows
rows = []
for l in data_lines:
    if not l.strip(): continue
    if set(l.strip()) <= set('|- '): continue # Skip extra separators
    cells = [c.strip() for c in l.split('|')[1:-1]]
    if len(cells) < len(header1):
        cells += [''] * (len(header1) - len(cells))
    rows.append(cells)

total_all = len(rows)
total_no_missing = 0
for r in rows:
    val_str = r[missing_idx].strip()
    # Extract number from string (e.g. "0 steps")
    nums = re.findall(r'\d+', val_str)
    if nums and int(nums[0]) == 0:
        total_no_missing += 1

total_with_missing = total_all - total_no_missing

def count_success(cols):
    ca = cn = cw = 0
    for r in rows:
        ok = False
        for col in cols:
            if col is None or col < 0 or col >= len(r): continue
            cell = r[col].lower()
            if 'success' in cell:
                ok = True
                break

        if ok:
            ca += 1
            # Check missing steps status for this row
            val_str = r[missing_idx].strip()
            nums = re.findall(r'\d+', val_str)
            if nums and int(nums[0]) == 0:
                cn += 1
            else:
                cw += 1
    return ca, cn, cw

results = {}
for t in ['recdroid', 'yakusu', 'roam']:
    cols = tool_indices.get(t, [])
    if not cols:
        results[t] = (0, 0, 0)
    else:
        results[t] = count_success(cols)

def pct(n, d):
    return round((n / d * 100) if d > 0 else 0.0, 2)

lines_out = []
lines_out.append('tool,all_reports_percent,reports_no_missing_percent,reports_with_missing_percent,all_counts,total_no_missing,total_with_missing')
for t, (ca, cn, cw) in results.items():
    lines_out.append(f'{t},{pct(ca, total_all)},{pct(cn, total_no_missing)},{pct(cw, total_with_missing)},{ca},{cn},{cw}')

with open(out_path, 'w', encoding='utf-8') as f:
    f.write('\n'.join(lines_out) + '\n')
print('\n'.join(lines_out))
PY

# Section 4: Format the result
echo '<artisan_submit>'
artisan format --expected /workspace/expected.md --repro /workspace/repro.txt
echo '</artisan_submit>'

#!/usr/bin/bash
# Section 1: Write the expected table to /workspace/expected.md
cat > /workspace/expected.md << 'EOTABLE'
**Table 5: The Match Accuracy and Reproduction Rate for RQ5**

|           | Avg. Match Accuracy (%) | Reproduction Rate (%) |
| --------- | :---------------------: | :-------------------: |
| Roam-Sim  |            ??           |           ??          |
| Roam-Dist |            ??           |           ??          |
| Roam      |            ??           |           ??          |

EOTABLE
# Section 2: Download and extract the artifact
artisan get https://zenodo.org/records/11068809
# Section 3: Run the commands to reproduce the results
uvx --from pymupdf4llm python -c 'import sys, pymupdf4llm as p; sys.stdout.write(p.to_markdown(sys.argv[1]))' ROAM-Artifact/ROAM-Artifact/Evaluation/results.pdf > /workspace/results.md
python3 - <<'PY'
import re, sys, csv

fn = "/workspace/results.md"
with open(fn, "r", encoding="utf-8") as f:
    lines = [l.rstrip("\n") for l in f]

def clean(s: str) -> str:
    s = re.sub(r"<.*?>", "", s)
    return s.strip()

# 1) Find the two header lines
hdr1_idx = None
for i, l in enumerate(lines):
    if l.startswith("|") and ("ROAM" in l and "ROAM-Sim" in l and "ROAM-Dist" in l):
        hdr1_idx = i
        break
if hdr1_idx is None:
    for i, l in enumerate(lines):
        if l.startswith("|") and "Issue id" in l:
            hdr1_idx = i - 1 if i > 0 else i
            break
if hdr1_idx is None:
    print("ERROR: header not found", file=sys.stderr); sys.exit(1)

hdr2_idx = None
for j in range(hdr1_idx + 1, min(len(lines), hdr1_idx + 20)):
    if lines[j].startswith("|") and re.search(r"(Issue id|Match|Reproduction)", lines[j], re.I):
        hdr2_idx = j
        break
if hdr2_idx is None:
    print("ERROR: subheader not found", file=sys.stderr); sys.exit(1)

cols1 = [clean(c) for c in lines[hdr1_idx].split("|")[1:-1]]
cols2 = [clean(c) for c in lines[hdr2_idx].split("|")[1:-1]]

# 2) Resolve per-tool subcolumn indices in a *local window* after the tool header.
#    Do NOT fall back to the first global "Match"/"Reproduction" – that mixes tools.
def find_tool_base(label: str) -> int:
    try:
        return cols1.index(label)
    except ValueError:
        for i, v in enumerate(cols1):
            if v and label in v:
                return i
        raise ValueError(f"tool header {label} not found")

def find_subcols(base: int, window: int = 12) -> tuple[int, int]:
    match_idx = repro_idx = None
    for off in range(0, window):
        idx = base + off
        if idx >= len(cols2): break
        h = cols2[idx].lower()
        if match_idx is None and "match" in h:
            match_idx = idx
        if repro_idx is None and ("repro" in h or "reproduction" in h):
            repro_idx = idx
        if match_idx is not None and repro_idx is not None:
            return match_idx, repro_idx
    raise ValueError(f"cannot locate subcolumns for base={base} within window={window}")

targets = ["ROAM-Sim", "ROAM-Dist", "ROAM"]
results = {}
for t in targets:
    base = find_tool_base(t)
    mi, ri = find_subcols(base, window=12)
    results[t] = {"match_idx": mi, "repro_idx": ri, "matches": [], "successes": 0, "count": 0}

# 3) Locate start of data: skip the alignment row like | --- |: ...:
data_start = hdr2_idx + 1
align_re = re.compile(r"^\|\s*(?::?-{3,}:?\s*\|)+\s*$")
while data_start < len(lines) and align_re.match(lines[data_start]):
    data_start += 1

# 4) Scan rows
truthy = {"success", "1", "true"}
falsy  = {"failure", "0", "false", "false positive"}  # "false positive" counts as NOT success

for i in range(data_start, len(lines)):
    l = lines[i]
    if not l.startswith("|"):
        continue
    cells = [c.strip() for c in l.split("|")[1:-1]]
    if len(cells) < len(cols2):
        # allow short/truncated lines, but keep indexing safe
        pass
    for t, info in results.items():
        mi, ri = info["match_idx"], info["repro_idx"]
        # match accuracy
        if mi < len(cells):
            mv = cells[mi]
            # Accept either 0..1 or already-percentage; normalize to 0..1 if needed
            try:
                raw = re.sub(r"[^\d\.eE\-\+]", "", mv)
                if raw:
                    val = float(raw)
                    # Heuristic: values > 1 are likely percentages already (e.g., 66.7), convert to 0..1
                    if val > 1.0000001:
                        val = val / 100.0
                    info["matches"].append(val)
            except Exception:
                pass
        # reproduction result
        if ri < len(cells):
            rv = cells[ri].strip().lower()
            if rv:  # only count rows where this tool has a reproduction value
                info["count"] += 1
                if rv in truthy:
                    info["successes"] += 1
                # anything else (including "false positive") counts as not-success

# 5) Write summary
out_fn = "/workspace/repro.txt"
with open(out_fn, "w", newline="", encoding="utf-8") as csvf:
    w = csv.writer(csvf)
    w.writerow(["Tool","Avg. Match Accuracy (%)","Reproduction Rate (%)"])
    for t in targets:
        info = results[t]
        avg_match = (sum(info["matches"]) / len(info["matches"])) * 100 if info["matches"] else 0.0
        denom = info["count"]
        repro_rate = (info["successes"] / denom) * 100 if denom > 0 else 0.0
        w.writerow([t, f"{avg_match:.2f}", f"{repro_rate:.2f}"])
print("/workspace/repro.txt")
PY
# Section 4: Format the result into the expected table with artisan format and surround with the required <artisan_submit> block
echo '<artisan_submit>'
artisan format --expected /workspace/expected.md --repro /workspace/repro.txt
echo '</artisan_submit>'

